import sys
from collections import defaultdict

def find_largest_x_and_permutation(n, S):
    def dfs(node, visited, path, x):
        if node in visited:
            return False
        visited[node] = True
        path.append(node)
        if len(path) == (1 << x):
            return True
        for neighbor in graph[node]:
            if dfs(neighbor, visited, path, x):
                return True
        path.pop()
        return False

    max_x = 0
    for x in range(19):
        if (1 << x) > n:
            break
        graph = defaultdict(list)
        for i in range(1 << x):
            for j in range(x):
                neighbor = i ^ (1 << j)
                if neighbor < (1 << x) and (i ^ neighbor) in S:
                    graph[i].append(neighbor)
        visited = [False] * (1 << x)
        path = []
        if dfs(0, visited, path, x):
            max_x = x

    return max_x, list(range(1 << max_x)) if max_x == 0 else path

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    S = set(map(int, input[1:]))
    x, permutation = find_largest_x_and_permutation(n, S)
    print(x)
    print(' '.join(map(str, permutation)))

main()
